'use client';

import { useDraggable } from '@dnd-kit/core';
import { Package, Layout, Zap, MoreVertical } from 'lucide-react';
import { cn } from '@/lib/utils';
import { EntityType } from '@/lib/types';

interface DraggableSidebarItemProps {
    id: string;
    type: EntityType;
    label: string;
    data: any;
    vendorName?: string;
}

export function DraggableSidebarItem({ id, type, label, data, vendorName }: DraggableSidebarItemProps) {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: `sidebar-${id}`,
        data: { type, label, entityId: id, source: 'sidebar', payload: data }
    });

    const getIcon = () => {
        switch (type) {
            case 'product': return <Package className="w-4 h-4" />;
            case 'vendor': return <Layout className="w-4 h-4" />;
            case 'solution': return <Zap className="w-4 h-4" />;
            default: return <Package className="w-4 h-4" />;
        }
    };

    const getColorClass = () => {
        switch (type) {
            case 'product': return "bg-blue-500/20 text-blue-400";
            case 'vendor': return "bg-purple-500/20 text-purple-400";
            case 'solution': return "bg-teal-500/20 text-teal-400";
            default: return "bg-gray-500/20 text-gray-400";
        }
    };

    return (
        <div
            ref={setNodeRef}
            {...listeners}
            {...attributes}
            className={cn(
                "group flex items-center justify-between p-3 rounded-xl border border-white/5 bg-white/5 backdrop-blur-sm cursor-grab active:cursor-grabbing hover:bg-white/10 hover:border-white/20 transition-all duration-200",
                isDragging && "opacity-40 grayscale scale-95"
            )}
        >
            <div className="flex items-center gap-3">
                <div className={cn("w-8 h-8 rounded-lg flex items-center justify-center", getColorClass())}>
                    {getIcon()}
                </div>
                <div className="flex flex-col">
                    <span className="text-sm font-medium text-white/90">{label}</span>
                    {vendorName && (
                        <span className="text-[10px] text-white/40 uppercase tracking-wider">{vendorName}</span>
                    )}
                </div>
            </div>
            <MoreVertical className="w-4 h-4 text-white/20 group-hover:text-white/50 transition-colors" />
        </div>
    );
}
